return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=3; plural=(((((((0 == 0)) && ((((n == 0)) == 0))) && (((n % 1000000) == 0))) && ((0 == 0))) || ((((0 >= 0 && 0 <= 5)) == 0))) ? 1 : ((n == 1)) ? 0 : 2);','language'=>'es_ES','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Crea copias de seguridad de tus archivos y base de datos de WordPress en tu propio almacenamiento (Dropbox, Google Drive, Cloudflare R2, Amazon S3 o cualquier bucket compatible con S3), los restaura de una sola vez e importa copias de seguridad creadas por otros plugins de copia de seguridad y migración.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Copias de seguridad','Get Pro: schedules, several storages, encryption'=>'Consigue Pro: programaciones, varios almacenamientos, cifrado','Working…'=>'Procesando…','Finished'=>'Terminado','Failed'=>'Fallido','Cancelled'=>'Cancelado','Cancel'=>'Cancelar','Restore'=>'Restaurar','Delete'=>'Eliminar','Delete this backup from your storage? This cannot be undone.'=>'¿Eliminar esta copia de seguridad de tu almacenamiento? Esta acción no se puede deshacer.','No backups yet. Press “Back up now” to make the first one.'=>'Aún no hay copias de seguridad. Pulsa «Hacer copia de seguridad ahora» para crear la primera.','Reading your storage…'=>'Leyendo tu almacenamiento…','a complete backup, as opposed to an incremental oneFull backup'=>'Copia de seguridad completa','a backup holding only what changed since an earlier oneIncremental backup'=>'Copia de seguridad incremental','Encrypted'=>'Cifrado','From another site'=>'Desde otro sitio','Database'=>'Base de datos','Files'=>'Archivos','Uploading %1$s: %2$s%%'=>'Subiendo %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Inicia sesión en Dropbox en la ventana que se ha abierto y, a continuación, pega el código que te muestra Dropbox:','Saved.'=>'Guardado.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'¿Eliminar este destino del plugin? Las copias de seguridad almacenadas en él no se eliminarán.','Reload the page to see the restored site.'=>'Recarga la página para ver el sitio restaurado.','Storage'=>'Almacenamiento','Import & migrate'=>'Importar y migrar','Settings'=>'Ajustes','Sections'=>'Secciones','Google Drive is connected.'=>'Google Drive está conectado.','Google Drive could not be connected.'=>'No se pudo conectar Google Drive.','Details'=>'Detalles','Back up now'=>'Hacer copia de seguridad ahora','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Las copias de seguridad van a tu propio almacenamiento, no a este servidor. Primero <a href="%s">conecta tu almacenamiento</a>.','What to back up'=>'Qué respaldar','Files and database'=>'Archivos y base de datos','Database only'=>'Solo base de datos','Files only'=>'Solo archivos','Note (optional)'=>'Nota (opcional)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Cada parte se sube a tu almacenamiento y se elimina de este servidor antes de que se cree la siguiente, por lo que la copia de seguridad nunca ocupa espacio en tu alojamiento.','Your backups'=>'Tus copias de seguridad','Refresh'=>'Actualizar','Restore this backup'=>'Restaurar esta copia de seguridad','Passphrase'=>'Frase de contraseña','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Entiendo que esto sustituye los archivos y la base de datos de este sitio por los de la copia de seguridad. Se conservan los archivos que no están en la copia de seguridad.','Recent activity'=>'Actividad reciente','Backup'=>'Copia de seguridad','Restore / import'=>'Restaurar / importar','Running'=>'En ejecución','Your storage'=>'Tu almacenamiento' . "\0" . 'Tus destinos de almacenamiento' . "\0" . 'Tus destinos de almacenamiento','No storage yet. Choose where your backups go below.'=>'Aún no hay almacenamiento. Elige abajo dónde van tus copias de seguridad.','Ready'=>'Listo','Not connected'=>'No conectado','Connect'=>'Conectar','Test'=>'Probar','Edit'=>'Editar','Remove'=>'Eliminar','Add storage'=>'Añadir almacenamiento','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Las copias de seguridad van a un único destino de almacenamiento. Para usar uno diferente, edita o elimina el anterior.','Kind of storage'=>'Tipo de almacenamiento','Name (for you)'=>'Nombre (para ti)','Provider'=>'Proveedor','Cloudflare account id'=>'ID de cuenta de Cloudflare','Endpoint address'=>'Dirección del extremo','Region'=>'Región','Bucket'=>'Bucket','Access key id'=>'ID de clave de acceso','Secret access key'=>'Clave de acceso secreta','Leave empty to keep the saved key'=>'Déjalo vacío para conservar la clave guardada','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Para Cloudflare R2: en el panel de control de Cloudflare, abre R2, crea un bucket, luego ve a «Manage R2 API tokens» → crea un token con permisos de Object Read & Write para ese bucket y copia aquí el access key id y el secret.','Dropbox app key'=>'Clave de la app de Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Crea una aplicación en dropbox.com/developers/apps (Scoped access, App folder) con los permisos files.content.read, files.content.write y files.metadata.read, y copia su App key aquí. Guarda y luego pulsa Connect.','OAuth client id'=>'ID de cliente OAuth','OAuth client secret'=>'Secreto de cliente de OAuth','Leave empty to keep the saved secret'=>'Déjalo vacío para conservar el secreto guardado','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'En Google Cloud Console, activa la Google Drive API y, a continuación, crea un cliente de OAuth de tipo «Web application» con esta dirección como URI de redireccionamiento autorizado:','Save, then press Connect. The plugin only sees the files it creates.'=>'Guarda y luego pulsa Conectar. El plugin solo ve los archivos que crea.','Folder inside the storage (optional)'=>'Carpeta dentro del almacenamiento (opcional)','Save storage'=>'Ahorra almacenamiento','Import a backup from another plugin or host'=>'Importa una copia de seguridad desde otro plugin o alojamiento','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Importa un sitio desde una copia de seguridad creada por UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate o cualquier archivo zip/tar de un sitio de WordPress con su volcado .sql. El contenido va a wp-content y la base de datos reemplaza la de este sitio; las direcciones se cambian automáticamente a las de este sitio.','Upload from your computer'=>'Subir desde tu ordenador','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Elige todos los archivos de la copia de seguridad a la vez (UpdraftPlus crea varios). Los archivos grandes se envían en partes pequeñas, por lo que el límite de subida de tu alojamiento no se aplica.','Or from links (Google Drive, Dropbox or any download address)'=>'O desde enlaces (Google Drive, Dropbox o cualquier dirección de descarga)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Un enlace por línea. Para Google Drive y Dropbox, comparte el archivo con «cualquiera que tenga el enlace» y pega ese enlace; desactiva el uso compartido después.','Or a file already on this server'=>'O un archivo que ya esté en este servidor','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Sube los archivos por FTP o mediante el administrador de archivos de tu alojamiento a %s y recarga esta página.','Or a deploy code from another site'=>'O un código de despliegue de otro sitio','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Si otro sitio te dio un código de despliegue de Zinn® Backups, pégalo aquí para copiar esa copia de seguridad en este sitio sin compartir sus claves de almacenamiento. Un código funciona durante unas horas; trátalo como una contraseña.','Passphrase (only if that backup is encrypted)'=>'Frase de contraseña (solo si esa copia de seguridad está cifrada)','Import'=>'Importar','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Entiendo que la importación reemplaza el contenido y la base de datos de este sitio. Después, inicia sesión con una cuenta del sitio importado.','Moving to Zinn® hosting?'=>'¿Te vas a mudar al alojamiento web de Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® puede migrar tu sitio desde tu antiguo proveedor por ti. Si tu antiguo proveedor no te ofrece acceso por FTP, SSH o panel de control, instala Zinn® Migrate en el sitio antiguo; creará un único archivo que puedes importar aquí o entregar a Zinn®.','What goes into a backup'=>'Qué incluye una copia de seguridad','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Incluye los archivos propios de WordPress (wp-admin, wp-includes). Normalmente no es necesario: WordPress siempre se puede reinstalar.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Excluye también estas carpetas o archivos (uno por línea, relativo a la carpeta de WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Siempre excluidos: cachés, espacio temporal de actualizaciones y las carpetas de archivo de otros plugins de copia de seguridad:','Size of each part (MB)'=>'Tamaño de cada parte (MB)','Save settings'=>'Guardar ajustes','A backup part could not be opened for writing. Check that wp-content has free space.'=>'No se ha podido abrir una parte de la copia de seguridad para escribir. Comprueba que wp-content tenga espacio libre.','A backup part could not be written. Check that wp-content has free space.'=>'No se pudo escribir una parte de la copia de seguridad. Comprueba que wp-content tenga espacio libre.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Conecta primero un destino de almacenamiento en la pestaña Storage: las copias de seguridad se guardan en tu propio almacenamiento, no en este servidor.','Multisite networks are not supported yet.'=>'Las redes multisitio aún no son compatibles.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'El PHP de este servidor no tiene la extensión ZipArchive. Pide a tu proveedor de alojamiento que la active.','Starting'=>'Iniciando','Listing files'=>'Listando archivos','Backing up the database'=>'Creando una copia de seguridad de la base de datos','Packing files'=>'Empaquetando archivos','Uploading to your storage'=>'Subiendo a tu almacenamiento','Finishing'=>'Finalizando','The backup reached an unknown stage.'=>'La copia de seguridad alcanzó una etapa desconocida.','Backup %s started.'=>'Copia de seguridad de %s iniciada.','Found %1$s files (%2$s).'=>'Se encontraron %1$s archivos (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Base de datos: %1$d tablas, %2$s filas, %3$s comprimido.','Backup complete: %1$s stored in %2$d destination.'=>'Copia de seguridad completada: %1$s guardado en %2$d destino.' . "\0" . 'Copia de seguridad completada: %1$s guardado en %2$d destinos.' . "\0" . 'Copia de seguridad completada: %1$s guardado en %2$d destinos.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Algunas partes ya subidas no se pudieron eliminar de tu almacenamiento; están en una carpeta de copia de seguridad incompleta y nunca se ofrecerán para restaurar.','A storage destination was removed while the backup was running.'=>'Se eliminó un destino de almacenamiento mientras se ejecutaba la copia de seguridad.','That is not a backup folder.'=>'Esa no es una carpeta de copia de seguridad.','That storage destination is no longer saved on this site.'=>'Ese destino de almacenamiento ya no está guardado en este sitio.','Later incremental backups are built on this one. Delete those first.'=>'Las copias de seguridad incrementales posteriores se basan en esta. Elimínalas primero.','This file is not an encrypted Zinn® Backups file.'=>'Este archivo no es un archivo cifrado de Zinn® Backups.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'No se pudo descifrar la copia de seguridad: la frase de contraseña es incorrecta o el archivo está dañado.','The encrypted backup file is incomplete.'=>'El archivo de copia de seguridad cifrado está incompleto.','The database file could not be written. Check that wp-content has free space.'=>'No se pudo escribir el archivo de base de datos. Comprueba que wp-content tenga espacio libre.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Ese no es un código de despliegue. Un código de despliegue comienza con zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Ese código de despliegue está dañado. Cópialo de nuevo desde el otro sitio.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'El código de despliegue ha caducado o se ha eliminado su copia de seguridad. Crea un nuevo código en el otro sitio.','That deploy code does not point at a Zinn® Backups backup.'=>'Ese código de despliegue no apunta a una copia de seguridad de Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'El código de despliegue ha caducado. Crea un código nuevo en el otro sitio.','The server stopped honouring partial downloads. Start the import again.'=>'El servidor ha dejado de admitir descargas parciales. Vuelve a iniciar la importación.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'El enlace ha abierto una página web en lugar de un archivo. Para Google Drive y Dropbox, comparte el archivo con «cualquiera que tenga el enlace» y pega ese enlace.','The link answered with HTTP %d.'=>'El enlace respondió con HTTP %d.','The file list could not be written.'=>'No se ha podido escribir la lista de archivos.','The storage service could not be reached: %s'=>'No se ha podido conectar con el servicio de almacenamiento: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s respondió con HTTP %2$d: %3$s','no details given'=>'No se proporcionaron detalles','You are not allowed to manage backups.'=>'No tienes permiso para gestionar copias de seguridad.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Marca la casilla para confirmar que la restauración sustituye los archivos y la base de datos de este sitio.','Save the destination first.'=>'Guarda el destino primero.','Connected: a test file was written and removed.'=>'Conectado: se ha escrito y eliminado un archivo de prueba.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Introduce primero la clave de la app de tu aplicación de Dropbox (consulta los pasos junto al formulario).','This kind of storage does not sign in.'=>'Este tipo de almacenamiento no inicia sesión.','The sign-in expired. Press Connect again.'=>'La sesión ha caducado. Pulsa Conectar de nuevo.','Dropbox is connected.'=>'Dropbox está conectado.','Settings saved.'=>'Ajustes guardados.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Se está ejecutando otra copia de seguridad, restauración o importación. Espera a que termine o cancela el proceso.','The upload was not started properly. Start again.'=>'La subida no se ha iniciado correctamente. Empieza de nuevo.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'El fragmento no llegó. Es posible que tu servidor límite el tamaño de las subidas; inténtalo de nuevo.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Marca la casilla para confirmar que la importación sustituye el contenido y la base de datos de este sitio.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Elige un archivo para importar: súbelo, pega un enlace o elige uno de la carpeta de importación.','Hosting customer? Get %1$d%% off %2$s'=>'¿Cliente de alojamiento? Consigue un %1$d%% de descuento en %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Como cliente de alojamiento de Zinn Digital®, recibes un código personal con un %d%% de descuento en tu primer pago. Las renovaciones se realizan al precio habitual.','Get my %d%% code and go to checkout'=>'Consigue mi código del %d%% y ve a pagar','Sorry, you are not allowed to do that.'=>'Lo siento, no tienes permiso para hacer eso.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Este descuento es para clientes con un plan de alojamiento de pago al corriente. Las pruebas gratuitas no son válidas.','You have already used your hosting-customer discount for this plugin.'=>'Ya has utilizado tu descuento de cliente de alojamiento para este plugin.','We could not get your code just now. Please try again in a few minutes.'=>'No hemos podido obtener tu código en este momento. Por favor, inténtalo de nuevo en unos minutos.','Reading the backup'=>'Leyendo la copia de seguridad','Downloading the archive'=>'Descargando el archivo','Recognising the archive'=>'Reconociendo el archivo','Restoring files'=>'Restaurando archivos','Downloading the database'=>'Descargando la base de datos','Restoring the database'=>'Restaurando la base de datos','Updating the site address'=>'Actualizando la dirección del sitio','Switching to the restored database'=>'Cambiando a la base de datos restaurada','The restore reached an unknown stage.'=>'La restauración ha alcanzado una etapa desconocida.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Esta carpeta no contiene ninguna copia de seguridad completa de Zinn® Backups (falta el manifiesto).','This backup is encrypted. Enter its passphrase to restore it.'=>'Esta copia de seguridad está cifrada. Introduce su frase de contraseña para restaurarla.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Esta copia de seguridad incremental necesita la copia de seguridad %s, que ya no está en el almacenamiento.','Restoring the backup of %1$s (%2$d file parts).'=>'Restaurando la copia de seguridad de %1$s (%2$d partes de archivo).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'No se pudo sobrescribir el archivo %1$s porque este sitio no tiene permiso para modificarlo, y se dejó tal como está: %2$s' . "\0" . 'No se han podido sobrescribir %1$s archivos porque este sitio no tiene permiso para modificarlos, y se han dejado tal como están: %2$s' . "\0" . 'No se han podido sobrescribir %1$s archivos porque este sitio no tiene permiso para modificarlos, y se han dejado tal como están: %2$s','Restored %s files.'=>'Se han restaurado %s archivos.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s no coincidió con su suma de comprobación después de descargarlo. La copia en el almacenamiento podría estar dañada.','%s did not arrive. Upload it again.'=>'%s no llegó. Súbelo de nuevo.','Recognised: %s.'=>'Reconocido: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Se han importado %1$s archivos en wp-content (%2$s omitidos: cachés, drop-ins y carpetas de otros plugins de copia de seguridad).','The archive has no database dump, so only files were imported.'=>'El archivo no contiene una copia de la base de datos, por lo que solo se importaron los archivos.','Database restored into %d temporary tables.'=>'Base de datos restaurada en %d tablas temporales.','%s has no WordPress tables in it and was skipped.'=>'%s no contiene tablas de WordPress y se ha omitido.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'La base de datos de la copia de seguridad no tiene tablas de WordPress, por lo que no se ha sustituido nada.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Esta copia de seguridad es de una red multisitio. No se admite la restauración de una red en un sitio único.','Moving the content from %1$s to %2$s.'=>'Moviendo el contenido de %1$s a %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Restauración completada. Si has cerrado sesión, inicia sesión con una cuenta del sitio restaurado.','Restore complete.'=>'Restauración completada.','%1$s — trying again in %2$d seconds.'=>'%1$s: reintentando en %2$d segundos.','Cancelled.'=>'Cancelado.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Las copias de seguridad van a un destino de almacenamiento. Edita o elimina el que tienes para usar uno diferente.','The database file could not be opened.'=>'No se pudo abrir el archivo de la base de datos.','The database refused a statement from the backup: %1$s (%2$s…)'=>'La base de datos rechazó una sentencia de la copia de seguridad: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'No se han podido sustituir las tablas restauradas: %s. Tu sitio no ha cambiado.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'No hay ninguna carpeta con permisos de escritura para los archivos temporales de copia de seguridad. Haz que wp-content sea modificable e inténtalo de nuevo.','Could not create a folder for this job.'=>'No se pudo crear una carpeta para esta tarea.','%s — guides and services'=>'%s: guías y servicios','User guides'=>'Guías de usuario','Read the %s user guide'=>'Lee la guía del usuario de %s','Hide this'=>'Ocultar esto','Zinn® hosting for WordPress'=>'Alojamiento de Zinn® para WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, copias de seguridad diarias, migración gratuita y un panel de control diseñado para personas que gestionan más de un sitio.','The Zinn® marketplace'=>'El mercado de Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Compra y vende sitios establecidos, dominios y ubicaciones de enlaces, con el dinero guardado de forma segura hasta que ambas partes estén satisfechas.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — contrata a personas que se dedican a esto profesionalmente','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Nuestro mercado global de freelancers: explora más de 10 000 servicios listos para usar de redactores, diseñadores, desarrolladores y especialistas en SEO, o publica un proyecto y deja que envíen sus propuestas.','See the Zinn Digital® release notes.'=>'Consulta las notas de la versión de Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'El servicio de actualizaciones de Zinn® no ha proporcionado un enlace de descarga para esta actualización. Comprueba que este sitio pueda conectarse a la plataforma Zinn® e inténtalo de nuevo.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'No se pudo descargar la actualización desde el servicio de actualizaciones de Zinn® (%s). Inténtalo de nuevo en unos minutos.','The downloaded update failed its integrity check and was not installed.'=>'La actualización descargada no superó la comprobación de integridad y no se instaló.','The zip archive could not be opened. It may be damaged or incomplete.'=>'No se ha podido abrir el archivo zip. Puede que esté dañado o incompleto.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Este archivo .wpress usa un formato que no podemos leer (puede estar comprimido o cifrado por All-in-One WP Migration). Expórtalo de nuevo sin cifrado.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Este es un archivo «DupArchive» (.daf) de Duplicator. En Duplicator, vuelve a crear el paquete con el formato de archivo configurado en ZIP y luego impórtalo.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Esta copia de seguridad de la base de datos de UpdraftPlus está cifrada. Descífrala en UpdraftPlus (o desactiva el cifrado de la base de datos y vuelve a crear una copia de seguridad), y luego impórtala.','Database dump'=>'Volcado de base de datos','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s no es un archivo de copia de seguridad que podamos leer (zip, tar, tar.gz, .wpress, .sql o .sql.gz).','Website archive'=>'Archivo del sitio web','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s no contiene contenido de WordPress (no tiene carpeta wp-content ni volcado de base de datos).','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Este archivo .wpress está cifrado o comprimido por All-in-One WP Migration. Expórtalo de nuevo con el cifrado y la compresión desactivados y luego impórtalo.','Other S3-compatible storage'=>'Otro almacenamiento compatible con S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 o compatible con S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'No se han podido leer las claves de almacenamiento en este sitio. Vuelve a introducir la clave secreta en la pestaña Almacenamiento.','This kind of storage is not known.'=>'Este tipo de almacenamiento no se conoce.','Choose a kind of storage.'=>'Elige un tipo de almacenamiento.','Enter the bucket name and the access key.'=>'Introduce el nombre del bucket y la clave de acceso.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Introduce tu ID de cuenta de Cloudflare (o el endpoint completo de R2).','Enter the endpoint address of your storage.'=>'Introduce la dirección del punto de conexión de tu almacenamiento.','Enter the OAuth client id from your Google Cloud project.'=>'Introduce el OAuth client id de tu proyecto de Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox no devolvió un token de actualización. Inicia la conexión de nuevo.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox no está conectado. Conéctalo de nuevo en la pestaña Almacenamiento.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google no ha devuelto un token de actualización. Elimina este sitio del acceso de terceros de tu cuenta de Google y vuelve a conectarte.','That file is not in Google Drive any more.'=>'Ese archivo ya no está en Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive no está conectado. Conéctalo de nuevo en la pestaña Almacenamiento.','The storage service did not start the upload.'=>'El servicio de almacenamiento no inició la subida.','The storage service sent a reply that could not be read.'=>'El servicio de almacenamiento envió una respuesta que no se pudo leer.','A temporary backup file could not be read.'=>'No se pudo leer un archivo de copia de seguridad temporal.','A deploy link is read-only.'=>'Un enlace de despliegue es de solo lectura.','The deploy code has no link for a file this backup needs.'=>'El código de despliegue no tiene ningún enlace para un archivo que necesita esta copia de seguridad.','The deploy link'=>'El enlace de despliegue']];